    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    int remaining = k - n; // amount to add beyond all 'a'
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can add up to 25 to go from 'a' to 'z'
